# Focus: Semantic Search Applications
documents = {"policy": "reset password with verified email", "shipping": "track an order in order history"}
query = set("reset password email".split())
scores = {name: len(query & set(text.split())) for name,text in documents.items()}
print(sorted(scores.items(), key=lambda item: item[1], reverse=True))
# This is lexical overlap, not semantic embeddings.
